import { spawn } from "node:child_process";
import { writeFileSync } from "node:fs";
import { setTimeout as sleep } from "node:timers/promises";
const OUT = "C:/Users/fortn/AppData/Local/Temp";
const edge = spawn("C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe",
  ["--headless=new","--remote-debugging-port=9397","--user-data-dir="+OUT+"/edge-crop","about:blank"], { stdio: "ignore" });
async function t(){for(let i=0;i<40;i++){try{const r=await fetch("http://127.0.0.1:9397/json/list");const l=await r.json();const p=l.find(x=>x.type==="page");if(p)return p.webSocketDebuggerUrl;}catch{}await sleep(400);}throw new Error("no target");}
const ws=new WebSocket(await t());await new Promise(r=>ws.onopen=r);
let id=0;const pend=new Map();
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pend.has(m.id)){pend.get(m.id)(m);pend.delete(m.id);}};
const send=(m,p={})=>{const i=++id;ws.send(JSON.stringify({id:i,method:m,params:p}));return new Promise(r=>pend.set(i,r));};
await send("Runtime.enable");await send("Page.navigate",{url:"about:blank"});
const r = await send("Runtime.evaluate",{expression:`new Promise(function(res){
  var img = new Image();
  img.onload = function(){
    var c = document.createElement('canvas'); c.width = img.width; c.height = img.height;
    var x = c.getContext('2d'); x.drawImage(img, 0, 0);
    var id = x.getImageData(0, 0, c.width, c.height), dd = id.data;
    var minX = c.width, minY = c.height, maxX = 0, maxY = 0;
    for (var y = 0; y < c.height; y++) for (var xx = 0; xx < c.width; xx++) {
      var i = (y * c.width + xx) * 4;
      if (dd[i+3] > 24) { if (xx < minX) minX = xx; if (xx > maxX) maxX = xx; if (y < minY) minY = y; if (y > maxY) maxY = y; }
    }
    var pad = 6;
    minX = Math.max(0, minX - pad); minY = Math.max(0, minY - pad);
    maxX = Math.min(c.width - 1, maxX + pad); maxY = Math.min(c.height - 1, maxY + pad);
    var w = maxX - minX + 1, h = maxY - minY + 1;
    var W = 200, H = Math.round(h * (200 / w));
    var c2 = document.createElement('canvas'); c2.width = W; c2.height = H;
    var x2 = c2.getContext('2d'); x2.imageSmoothingEnabled = true; x2.imageSmoothingQuality = 'high';
    x2.drawImage(img, minX, minY, w, h, 0, 0, W, H);
    var id2 = x2.getImageData(0, 0, W, H), d2 = id2.data;
    for (var j = 0; j < d2.length; j += 4) if (d2[j+3] < 24) { d2[j]=0; d2[j+1]=0; d2[j+2]=0; d2[j+3]=0; }
    x2.putImageData(id2, 0, 0);
    res(c2.toDataURL('image/png'));
  };
  img.onerror = function(){ res('ERR'); };
  img.src = 'data:image/png;base64,';
})`, awaitPromise:true, returnByValue:true});
const data = r.result?.result?.value || "";
if (data.startsWith("data:image/png")) {
  writeFileSync("C:/Users/fortn/ember-site/assets/brand/logo-full.png", Buffer.from(data.split(",")[1], "base64"));
  console.log("logo cropped to ink");
} else console.log("FAILED:", data.slice(0,80));
ws.close();edge.kill();process.exit(0);
